const $=id=>document.getElementById(id), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const agents=[{name:'Nico',role:'Coordinador',color:'#5e8c72',skin:'#e3b18b',hair:'#384036',home:[-3,-3.6],icon:'👨🏻‍💼'},{name:'Luna',role:'Investigadora',color:'#c78461',skin:'#b67d58',hair:'#49332d',home:[3,-3.6],icon:'👩🏽‍💻'},{name:'Leo',role:'Creador',color:'#7c91b8',skin:'#efc69d',hair:'#74513a',home:[3,.7],icon:'👨🏻‍🎨'}];
let data;try{data=JSON.parse(localStorage.getItem('office3d-v1'));if(!data||!Array.isArray(data.tasks)||!Array.isArray(data.messages))throw Error()}catch{data={tasks:[],requests:[],activity:['Tu oficina 3D abrió sus puertas.'],messages:[[],[],[]]}}let active=0,editing=null;
const people=agents.map((a,i)=>({ ...a,i,pos:[...a.home],yaw:0,mode:'idle',route:[],timer:0,phase:Math.random()*5,queue:[],job:null,nextBreak:20+i*14}));
const stateNames={idle:'Disponible',walking:'Caminando',receiving:'Recibiendo tu orden',working:'Trabajando',waiting:'Espera tu aprobación',eating:'Comiendo',resting:'Descansando',visiting:'En tu escritorio'};
function save(){try{localStorage.setItem('office3d-v1',JSON.stringify(data))}catch{toast('El navegador no pudo guardar los cambios.')}}function log(s){data.activity.unshift(s);data.activity=data.activity.slice(0,60)}function toast(s){$('toast').textContent=s;$('toast').style.display='block';clearTimeout(window.tt);window.tt=setTimeout(()=>$('toast').style.display='none',3800)}
function render(){ $('team').innerHTML=people.map(p=>`<button class="agent" data-person="${p.i}"><span class="portrait" style="background:${p.color}25">${p.icon}</span><span><b>${p.name}</b><small>${p.role}</small><span class="status">● ${stateNames[p.mode]}</span></span><span class="arrow">↗</span></button>`).join('');$('request-count').textContent=data.requests.length;$('requests').innerHTML=data.requests.length?data.requests.map(r=>`<div class="request"><small>${agents[r.agent].name} · Solicitud simulada</small><b>Revisa mi propuesta</b><p>${esc(r.plan)}</p><div class="actions"><button data-approve="${r.id}">Aprobar</button><button class="secondary" data-edit="${r.id}">Editar</button><button class="secondary" data-reject="${r.id}">Rechazar</button></div></div>`).join(''):'<div class="empty">Cuando un agente necesite tu decisión, vendrá a tu escritorio y aparecerá aquí.</div>';$('task-count').textContent=data.tasks.length;$('tasks').innerHTML=data.tasks.length?data.tasks.slice().reverse().map(t=>`<div class="task"><b>${esc(t.text)}</b><small>${agents[t.agent].name} · ${esc(t.status)}</small>${t.result?`<p>${esc(t.result)}</p>`:''}</div>`).join(''):'<p class="footnote">Dale tu primera misión al equipo.</p>';$('activity').innerHTML=data.activity.slice(0,12).map(x=>`<div class="task">${esc(x)}</div>`).join('');save()}
function chat(){const p=people[active];$('chat-name').textContent=p.name+' · '+p.role;$('messages').innerHTML=(data.messages[active].length?data.messages[active]:[{text:'¡Hola! Dame una orden y caminaré hasta tu escritorio para recibirla. Puedes enviarme a comer o a descansar.'}]).map(m=>`<div class="message ${m.user?'user':''}">${esc(m.text)}</div>`).join('');$('messages').scrollTop=$('messages').scrollHeight;const busy=p.mode!=='idle';$('eat').disabled=busy;$('rest').disabled=busy;$('call').disabled=busy}
function openChat(i){active=i;chat();$('chat').showModal()}
function route(p,target,cb){p.mode='walking';p.route=[[0,p.pos[1]],[0,target[1]],[...target]].filter((q,i,arr)=>i===0||Math.hypot(q[0]-arr[i-1][0],q[1]-arr[i-1][1])>.01);p.after=cb;render()}
function setMode(p,m,seconds){p.mode=m;p.timer=seconds||0;render()}
function taskStatus(p,s){if(p.job){p.job.status=s;render()}}
function startJob(p){if(!p.queue.length||p.mode!=='idle')return;p.job=p.queue.shift();taskStatus(p,'Camino a tu escritorio');route(p,[-.7,3.8],()=>{p.yaw=-Math.PI/2;setMode(p,'receiving',2.5);$('scene-status').textContent=p.name+' está recibiendo tu orden.';log(p.name+' llegó a recibir: '+p.job.text);render()})}
function send(text,i){const t={id:crypto.randomUUID(),text,agent:i,status:'En cola'};data.tasks.push(t);data.messages[i].push({user:true,text},{text:'Orden registrada en la simulación. Me acercaré a tu escritorio para recibirla.'});people[i].queue.push(t);log('Le diste una orden a '+agents[i].name+'.');startJob(people[i]);render();toast(people[i].job===t?agents[i].name+' va a tu escritorio.':'Orden en cola: '+agents[i].name+' irá cuando termine.')}
function makeRequest(p){const t=p.job,plan='Misión: '+t.text+'\n\n1. Aclarar el objetivo y el resultado esperado.\n2. Dividir el trabajo en tres pasos concretos.\n3. Preparar un borrador para que lo revises.';data.requests.push({id:t.id,agent:p.i,plan});data.messages[p.i].push({text:'Preparé una propuesta de prueba. Necesito tu aprobación para continuar.'});taskStatus(p,'Por aprobar');log(p.name+' te pidió aprobar su plan.');route(p,[-.7,3.8+p.i*.45],()=>{p.yaw=-Math.PI/2;setMode(p,'waiting');toast(p.name+' está esperando tu decisión.');$('scene-status').textContent='Revisa el panel de solicitudes para responderle a '+p.name+'.'})}
function finish(p){const t=p.job;t.status='Completada · demo';t.result='Borrador simulado para: '+t.text+'\n\nObjetivo: escribe cómo se verá el resultado final.\nPrimer paso: elige una acción pequeña que puedas hacer hoy.\nSeguimiento: define una fecha para revisar tu avance.\n\nPropuesta aprobada:\n'+(t.plan||'');data.messages[p.i].push({text:t.result});log(p.name+' terminó una misión de prueba.');p.job=null;setMode(p,'idle');p.nextBreak=24+p.i*13;toast(p.name+' terminó. Revisa Misiones.');startJob(p)}
function breakTime(p,kind,automatic=false){if(p.mode!=='idle')return;const target=kind==='eating'?[4.4,-5]:[-4.3,.1];route(p,target,()=>{p.yaw=kind==='eating'?0:Math.PI/2;setMode(p,kind,automatic?8:12);log(p.name+(kind==='eating'?' está comiendo en la zona de café.':' está descansando en el sofá.'));render()})}
function tickPeople(dt,time){for(const p of people){p.phase+=dt*8;if(p.mode==='walking'){const q=p.route[0];if(q){const dx=q[0]-p.pos[0],dz=q[1]-p.pos[1],d=Math.hypot(dx,dz),step=dt*1.8;p.yaw=Math.atan2(dx,dz);if(d<=step){p.pos=[...q];p.route.shift()}else{p.pos[0]+=dx/d*step;p.pos[1]+=dz/d*step}}if(!p.route.length){const cb=p.after;p.after=null;if(cb)cb()}}else if(p.timer>0){p.timer-=dt;if(p.timer<=0){if(p.mode==='receiving'){taskStatus(p,'Preparando propuesta');route(p,p.home,()=>{p.yaw=0;setMode(p,'working',7)})}else if(p.mode==='working'){if(p.job?.approved)finish(p);else if(p.job)makeRequest(p);else setMode(p,'idle')}else if(p.mode==='eating'||p.mode==='resting'||p.mode==='visiting'){route(p,p.home,()=>{p.yaw=0;setMode(p,'idle');p.nextBreak=30+p.i*11;startJob(p)})}}}else if(p.mode==='idle'){if(p.queue.length)startJob(p);else{p.nextBreak-=dt;if(p.nextBreak<=0)breakTime(p,p.i===1?'resting':'eating',true)}}}}
$('new').onclick=()=>$('order').showModal();document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>b.closest('dialog').close());$('team').onclick=e=>{const b=e.target.closest('[data-person]');if(b)openChat(+b.dataset.person)};$('order-form').onsubmit=e=>{e.preventDefault();const s=$('instruction').value.trim();if(s){send(s,+$('agent').value);$('instruction').value='';$('order').close()}};$('chat-form').onsubmit=e=>{e.preventDefault();const s=$('chat-input').value.trim();if(s){send(s,active);$('chat-input').value='';chat();$('chat').close()}};$('eat').onclick=()=>{breakTime(people[active],'eating');$('chat').close()};$('rest').onclick=()=>{breakTime(people[active],'resting');$('chat').close()};$('call').onclick=()=>{const p=people[active];if(p.mode==='idle')route(p,[-.7,3.8],()=>{p.yaw=-Math.PI/2;setMode(p,'visiting',6)});$('chat').close()};
$('requests').onclick=e=>{const b=e.target.closest('button');if(!b)return;const id=b.dataset.approve||b.dataset.reject||b.dataset.edit,r=data.requests.find(r=>r.id===id);if(!r)return;if(b.dataset.edit){editing=id;$('edit-text').value=r.plan;$('edit').showModal();return}const p=people[r.agent],t=data.tasks.find(t=>t.id===id);data.requests=data.requests.filter(r=>r.id!==id);if(b.dataset.approve){t.approved=true;t.plan=r.plan;t.status='Trabajando · demo';p.job=t;p.route=[];p.timer=0;route(p,p.home,()=>{p.yaw=0;setMode(p,'working',7)});log('Aprobaste el plan de '+p.name+'.');toast(p.name+' vuelve a trabajar.')}else{t.status='Rechazada';data.messages[p.i].push({text:'Propuesta rechazada. Puedes enviarme una nueva orden.'});p.job=null;p.timer=0;route(p,p.home,()=>{p.yaw=0;setMode(p,'idle');startJob(p)});log('Rechazaste el plan de '+p.name+'.')}render()};$('edit-form').onsubmit=e=>{e.preventDefault();const r=data.requests.find(r=>r.id===editing),s=$('edit-text').value.trim();if(r&&s){r.plan=s;log('Modificaste una propuesta.');render();$('edit').close()}};
