const director={pos:[-3,4.3],yaw:Math.PI,mode:'idle',color:'#44665b',skin:'#d7a57c',hair:'#3f3d32',i:3,phase:0};const labels=people.map(p=>{const b=document.createElement('button');b.className='label';b.onclick=()=>openChat(p.i);$('labels').append(b);return b});const db=document.createElement('button');db.className='label director';db.innerHTML='Tu escritorio<small>Dar una orden</small>';db.onclick=()=>$('order').showModal();$('labels').append(db);
