let pointers=new Map(),drag=null,pinch=0;canvas.onpointerdown=e=>{canvas.setPointerCapture(e.pointerId);pointers.set(e.pointerId,[e.clientX,e.clientY]);if(pointers.size===1)drag={x:e.clientX,y:e.clientY,angle,elev,moved:0};if(pointers.size===2){const a=[...pointers.values()];pinch=Math.hypot(a[0][0]-a[1][0],a[0][1]-a[1][1]);drag=null}};canvas.onpointermove=e=>{if(!pointers.has(e.pointerId))return;pointers.set(e.pointerId,[e.clientX,e.clientY]);if(pointers.size===2){const a=[...pointers.values()],d=Math.hypot(a[0][0]-a[1][0],a[0][1]-a[1][1]);distance=Math.max(11,Math.min(25,distance+(pinch-d)*.025));pinch=d}else if(drag){const dx=e.clientX-drag.x,dy=e.clientY-drag.y;angle=drag.angle-dx*.006;elev=Math.max(.35,Math.min(1.2,drag.elev+dy*.005));drag.moved=Math.hypot(dx,dy)}};canvas.onpointerup=e=>{if(drag&&drag.moved<6){const r=canvas.getBoundingClientRect(),x=e.clientX-r.left,y=e.clientY-r.top;let best=65,selected=-1;people.forEach(p=>{const q=project(p.pos[0],1.2,p.pos[1]),d=Math.hypot(q[0]-x,q[1]-y);if(d<best){selected=p.i;best=d}});if(selected>=0)openChat(selected)}pointers.delete(e.pointerId);drag=null};canvas.onpointercancel=e=>{pointers.delete(e.pointerId);drag=null};canvas.addEventListener('wheel',e=>{e.preventDefault();distance=Math.max(11,Math.min(25,distance+e.deltaY*.012))},{passive:false});$('zoomin').onclick=()=>distance=Math.max(11,distance-1.5);$('zoomout').onclick=()=>distance=Math.min(25,distance+1.5);$('rotate').onclick=()=>angle+=Math.PI/4;$('reset').onclick=()=>{angle=.67;elev=.68;distance=17};
gl.enable(gl.DEPTH_TEST);gl.disable(gl.CULL_FACE);let prev=performance.now();function frame(now){const dt=Math.min((now-prev)/1000,.06);prev=now;tickPeople(dt,now/1000);const rect=canvas.getBoundingClientRect();width=rect.width;height=rect.height;const ratio=Math.min(devicePixelRatio||1,1.8);if(canvas.width!==Math.round(width*ratio)||canvas.height!==Math.round(height*ratio)){canvas.width=Math.round(width*ratio);canvas.height=Math.round(height*ratio)}gl.viewport(0,0,canvas.width,canvas.height);gl.clearColor(.835,.885,.835,1);gl.clear(gl.COLOR_BUFFER_BIT|gl.DEPTH_BUFFER_BIT);const fit=width/height<1?1.3:1;const d=distance*fit,eye=[Math.sin(angle)*Math.cos(elev)*d,Math.sin(elev)*d+target[1],Math.cos(angle)*Math.cos(elev)*d];vp=mul(perspective(width/height),look(eye,target));gl.uniformMatrix4fv(loc.vp,false,vp);for(const o of objects)draw(o.shape,o.m,o.c);people.forEach(p=>character(p,now/1000));character(director,now/1000);updateLabels();requestAnimationFrame(frame)}requestAnimationFrame(frame);
